def apply(hou,save=False):
    if save:raise RuntimeError('Use protected VerifyFull persistence')
    asset=hou.node('/obj/StreetBuilding_DEV');core=asset.node('StreetBuildingCore')
    original={n:core.node(n).evalParm('snippet') for n in BEFORE}
    if all(original[n]==AFTER[n] for n in BEFORE):return {'status':'unchanged','saved':False}
    for n,s in original.items():
        if hashlib.sha256(s.encode()).hexdigest()!=BEFORE[n]:raise RuntimeError('Live precondition mismatch: '+n)
    try:
        for n,s in AFTER.items():core.node(n).parm('snippet').set(s)
        return {'status':'patched','saved':False,'nodes':list(AFTER)}
    except Exception:
        for n,s in original.items():core.node(n).parm('snippet').set(s)
        raise
